Lemma enc_depthA (M M' : word -> option byte) ov fb eb ek stk d d' :
  PECA.enc_atA RSEGS EE L ar M ov fb (PEC.ENC eb ek stk d) ->
  0 <= ov -> ov + 56 <= 2 ^ 64 -> (0 < ek -> 0 <= eb /\ eb + PEC.ESZ * PEC.ecap ek <= 2 ^ 64) ->
